#!/bin/bash
sed -i '/let total_bytes = if total_bytes == 0 {/,/};/c\        #[cfg(target_os = "linux")]\n        let total_bytes = if total_bytes == 0 {\n            let mut size: u64 = 0;\n            let fd = file.as_raw_fd();\n            unsafe {\n                if libc::ioctl(fd, 0x80081272, \&mut size) == 0 {\n                    size\n                } else {\n                    0\n                }\n            }\n        } else {\n            total_bytes\n        };\n\n        #[cfg(not(target_os = "linux"))]\n        let total_bytes = total_bytes;' src-tauri/src/engine/sanitizer.rs
